update public.techniques
set nombre_en = 'Tell series from parallel at a glance',
    descripcion_en = 'Before calculating anything, look at how the resistors are connected — that alone tells you which formulas apply.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Do the resistors form a single path, one after the other, with no forks? It is series — the current is the same in all of them.","Does each resistor have both ends connected to the same two points (nodes)? It is parallel — the voltage is the same in all of them.","Is there a series branch that at some stretch opens into 2 or more paths that then join again? It is a mixed circuit — it combines the two rules by parts.","A lone resistor, with no company, is technically both series and parallel with itself — no special formula is needed."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"The resistors form a single path, one after the other, with no forks. What type of connection is it?","opciones":["Series","Parallel","Mixed","None of the above"],"respuesta":"Series","explicacion":"It is the definition of series: a single path, the current is the same in all the resistors."},{"pregunta":"Each resistor has both ends connected to the same two points (nodes). What type of connection is it?","opciones":["Parallel","Series","Mixed","It cannot be known without the resistance values"],"respuesta":"Parallel","explicacion":"It is the definition of parallel: the same two shared nodes, the voltage is the same in all the resistors."},{"pregunta":"A series branch that at some stretch opens into 2 or more paths that then join again: what type of circuit is it?","opciones":["Mixed","Pure series","Pure parallel","It is not a valid circuit"],"respuesta":"Mixed","explicacion":"It combines the two rules by parts — the block that opens and joins again is the parallel part, the rest follows the series rules."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.circuito","despuesDePaso":0,"titulo":"Series","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":20}]},"vFuente":12,"mostrarValores":"ninguna","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":1,"titulo":"Parallel","topologia":{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":20}]},"vFuente":12,"mostrarValores":"ninguna","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":2,"titulo":"Mixed","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"Rs1","ohmios":10},{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"Rp1","ohmios":20},{"tipo":"resistor","id":"Rp2","ohmios":20}]}]},"vFuente":12,"mostrarValores":"ninguna","animarCorriente":true}]$leccion_en$::jsonb
    )
where slug = 'circuitia-reconocer-serie-vs-paralelo';

update public.techniques
set nombre_en = 'The formula for equivalent resistance in parallel (reciprocals)',
    descripcion_en = 'In parallel, the equivalent resistance is always SMALLER than the smallest of the individual resistances — a shortcut to check whether your calculation makes sense.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["In series, resistances add directly: $R_{\\text{eq}} = R_{1} + R_{2} + R_{3}$ — the more resistors, the more total resistance.","In parallel, the RECIPROCALS are added: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\frac{1}{R_{3}}$, and at the end you invert the result — the more resistors, the LESS total resistance.","Easy special case to remember: two equal resistors R in parallel give $\\frac{R}{2}$ — half, not double.","Quick sanity check: if your result of a parallel calculation came out GREATER than the smallest resistor of the branch, something went wrong — you inverted something too many or too few times."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"How is the equivalent resistance of resistors in SERIES calculated?","opciones":["They are added directly: $R_{\\text{eq}} = R_{1} + R_{2} + R_{3}$","The reciprocals are added and inverted","They are averaged","They are multiplied together"],"respuesta":"They are added directly: $R_{\\text{eq}} = R_{1} + R_{2} + R_{3}$","explicacion":"In series, the more resistors you add, the more total resistance — the sum is direct, without reciprocals."},{"pregunta":"How is the equivalent resistance of resistors in PARALLEL calculated?","opciones":["$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\frac{1}{R_{3}}$, and at the end the result is inverted","They are added directly, just like in series","The smallest is subtracted from the largest","Only the smallest resistance of the group is taken"],"respuesta":"$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\frac{1}{R_{3}}$, and at the end the result is inverted","explicacion":"In parallel the RECIPROCALS are added — the more resistors you add, the LESS total resistance, the opposite of series."},{"pregunta":"Two equal resistors of value R, connected in parallel, give an equivalent resistance of...","opciones":["$\\frac{R}{2}$","2R","R","$R^{2}$"],"respuesta":"$\\frac{R}{2}$","explicacion":"It is the easy special case to remember: half, not double — it works as a quick sanity check of any parallel calculation."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.resistenciaEquivalente","despuesDePaso":0,"modo":"serie","ohmios":[8,8]},{"tipo":"circuitia.resistenciaEquivalente","despuesDePaso":1,"modo":"paralelo","ohmios":[8,8]}]$leccion_en$::jsonb
    )
where slug = 'circuitia-formula-resistencia-paralelo';

update public.techniques
set nombre_en = 'When the voltage is shared and when the current is shared',
    descripcion_en = 'The key question so you do not get confused: "what is the same in all the resistors of this group — the voltage or the current?"',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["In SERIES: the current is the same for all (it has no other path to go through) — the voltage IS SPLIT among the resistors according to their size.","In PARALLEL: the voltage is the same for all (they are connected to the same 2 points) — the current IS SPLIT among the branches according to their resistance.","A resistor with more resistance, in series, gets MORE voltage ($V=IR$, same I); in parallel, it gets LESS current ($I=\\frac{V}{R}$, same V) — it is the inverse relationship in each case.","Ohm's law $(V=IR)$ always works for ONE specific resistor — the question of \"what is shared\" is about the GROUP, not about a lone resistor."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"In a group of resistors connected in SERIES, what is the same in all of them?","opciones":["The current","The voltage","The resistance","The power"],"respuesta":"The current","explicacion":"In series the current has no other path to go through — it is the same for all; the voltage is split according to the size of each resistor."},{"pregunta":"In a group of resistors connected in PARALLEL, what is the same in all of them?","opciones":["The voltage","The current","The resistance","The power"],"respuesta":"The voltage","explicacion":"In parallel they are all connected to the same 2 points, so the voltage is the same — the current is split according to the resistance of each branch."},{"pregunta":"In SERIES, a resistor with more resistance than its neighbors (same current for all) gets...","opciones":["More voltage","Less voltage","The same current as the others, but zero voltage","More current than the others"],"respuesta":"More voltage","explicacion":"By $V=IR$ with the same I for all, a bigger R gets a bigger V — it is the inverse of what happens in parallel (there, a bigger R gets LESS current)."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.circuito","despuesDePaso":0,"titulo":"Series: the current is the same","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":20}]},"vFuente":12,"mostrarValores":"corriente","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":1,"titulo":"Parallel: the voltage is the same","topologia":{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":20}]},"vFuente":12,"mostrarValores":"voltaje","animarCorriente":true}]$leccion_en$::jsonb
    )
where slug = 'circuitia-voltaje-vs-corriente-compartidos';

update public.techniques
set nombre_en = 'Reading a mixed circuit: identify the parallel block first',
    descripcion_en = 'A mixed circuit is solved from the inside out — the first step is always to find and "collapse" the parallel block into a single equivalent resistor.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Look for the group of resistors that share the same 2 nodes (the parallel block) — it is usually the smallest or most nested stretch of the drawing.","Calculate the equivalent resistance of THAT block alone, with the reciprocal formula — now you have a single \"virtual\" resistor in its place.","With the block already collapsed to a single value, the whole circuit becomes a simple series — add that value to the other series resistors.","To find the current/voltage of a specific resistor INSIDE the parallel block, you first need the voltage that reaches the whole block (previous step), and only then split it."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"When reading a mixed circuit, what is looked for and solved FIRST?","opciones":["The block of resistors in parallel (collapsing it to a single equivalent value)","The resistor with the largest value","The voltage source","The resistor closest to the source, however it is connected"],"respuesta":"The block of resistors in parallel (collapsing it to a single equivalent value)","explicacion":"A mixed circuit is solved from the inside out — the first step is always to find the group that shares the same 2 nodes and calculate its equivalent resistance."},{"pregunta":"Once the parallel block is collapsed to a single \"virtual\" resistor, how does the whole circuit look?","opciones":["Like a simple series, adding that value to the other series resistors","Like a new parallel block","It can no longer be solved","The same as before, unchanged"],"respuesta":"Like a simple series, adding that value to the other series resistors","explicacion":"It is the second step of the technique: with the block already reduced to a number, the rest of the circuit is treated with the simple series rules."},{"pregunta":"To find the voltage of a specific resistor INSIDE the parallel block, what do you need to calculate first?","opciones":["The voltage that reaches the whole parallel block","The current of the whole source","The resistance of any resistor outside the block","No previous calculation is needed"],"respuesta":"The voltage that reaches the whole parallel block","explicacion":"Only with the voltage of the whole block (which is split equally among all its branches, since it is parallel) can the current of a specific resistor inside be calculated."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.circuito","despuesDePaso":1,"titulo":"The parallel block","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"Rs1","ohmios":10},{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"Rp1","ohmios":20},{"tipo":"resistor","id":"Rp2","ohmios":20}]}]},"vFuente":12,"resaltarId":"Rp1","mostrarValores":"ninguna","animarCorriente":false},{"tipo":"circuitia.resistenciaEquivalente","despuesDePaso":2,"modo":"paralelo","ohmios":[20,20]}]$leccion_en$::jsonb
    )
where slug = 'circuitia-leer-mixto-por-el-bloque-paralelo';

update public.techniques
set nombre_en = 'Quickly estimate whether a current goes up or down without calculating everything',
    descripcion_en = 'Before taking out the calculator, reason with physical sense: more resistance in the path always slows the current more.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["If the resistance of a stretch increases, the TOTAL resistance of the circuit increases (or stays the same, it never goes down) — so the current the source delivers never goes up.","In a PARALLEL branch, changing the resistance of ONE branch does not affect the other sibling branches — each one still sees the same voltage as always, so its own current does not change.","In SERIES, any change in one resistor DOES affect all the others — the same current (now different) goes through all of them equally.","When the question is about a sibling resistor in a parallel block connected directly to the source, the most common and correct answer is \"it does not change\" — do not assume that every change somewhere affects the whole circuit."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"If the resistance of a stretch of the circuit increases, what happens to the TOTAL current the source delivers?","opciones":["It never goes up (it goes down or stays the same)","It always goes up","It always doubles","It does not depend on the total resistance"],"respuesta":"It never goes up (it goes down or stays the same)","explicacion":"More total resistance in the path always slows down (or equally) the current the source can deliver — it never increases it."},{"pregunta":"In a PARALLEL block connected directly to the source, if the resistance of ONE branch changes, what happens to the current of a SIBLING branch?","opciones":["It does not change","It always increases","It always decreases","It becomes zero"],"respuesta":"It does not change","explicacion":"Each parallel branch still sees the same (shared) voltage as always, so its own current ($I=\\frac{V}{R}$ with its own R, unchanged) is not affected by what happens in a sibling branch."},{"pregunta":"In SERIES, if the resistance of one resistor changes, what happens to the other resistors of that same branch?","opciones":["It affects all of them — the same current (now different) goes through all of them equally","Nothing happens to them, each one is independent","It only affects the resistor immediately after","It only affects the source, never other resistors"],"respuesta":"It affects all of them — the same current (now different) goes through all of them equally","explicacion":"In series they all share the same current — if that current changes (because the total resistance changed), it affects all the resistors of the branch equally, unlike a parallel branch."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.circuito","despuesDePaso":0,"titulo":"Before: R1 = 10Ω","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R1","mostrarValores":"corriente","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":0,"titulo":"After: R1 doubles to 20Ω","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":20},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R1","mostrarValores":"corriente","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":1,"titulo":"The sibling branch R3 does not change","topologia":{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"R1","ohmios":4},{"tipo":"resistor","id":"R2","ohmios":6},{"tipo":"resistor","id":"R3","ohmios":12}]},"vFuente":12,"resaltarId":"R3","mostrarValores":"corriente","animarCorriente":true}]$leccion_en$::jsonb
    )
where slug = 'circuitia-estimar-sube-o-baja-sin-calcular';

update public.techniques
set nombre_en = 'Pro Course: Fundamentals — Ohm''s law and series circuits',
    descripcion_en = 'What Ohm''s law says, why a series circuit shares a single current, and a complete worked example.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Ohm's law: $V = I\\cdot R$. The voltage across a resistor is directly proportional to the current through it, with the resistance as the proportionality factor — the bigger R is, the more voltage is needed for the same current.","In a SERIES circuit, the resistors are one behind the other forming a single path, with no forks — the charge has nowhere else to go, so the SAME current goes through all the resistors in the chain.","Worked example: a series circuit with $R_{1}=10\\,\\Omega$ and $R_{2}=20\\,\\Omega$, powered by a $12\\,\\text{V}$ source. First the equivalent resistance: $R_{\\text{eq}} = R_{1} + R_{2} = 10 + 20 = 30\\,\\Omega$. Then the total current with Ohm's law: $I = \\frac{V}{R_{\\text{eq}}} = \\frac{12}{30} = 0.4\\,\\text{A}$ — that is the current in the WHOLE circuit, in $R_{1}$ and in $R_{2}$ alike.","With that current, the voltage of each resistor comes from applying $V=IR$ to each one separately: $V_{R_{1}} = 0.4\\cdot 10 = 4\\,\\text{V}$, $V_{R_{2}} = 0.4\\cdot 20 = 8\\,\\text{V}$.","Check (you can always check): the sum of the voltages of each resistor has to give exactly the source voltage. $4\\,\\text{V} + 8\\,\\text{V} = 12\\,\\text{V}$ ✓ — it matches the source, confirming the split is right.","Common mistake to avoid: thinking that the current is also \"split\" among the resistors like the voltage — in series it is the other way round: the current is the same in all, and it is the VOLTAGE that is split according to the size of each resistor.","The rule is the same with more resistors. Example: $R_{1}=10\\,\\Omega$, $R_{2}=20\\,\\Omega$ and $R_{3}=30\\,\\Omega$ in series, with a $12\\,\\text{V}$ source. The equivalent resistance is $R_{\\text{eq}} = 10 + 20 + 30 = 60\\,\\Omega$ and the total current is $I = \\frac{12}{60} = 0.2\\,\\text{A}$, the same in the three resistors. Their voltages are $V_{R_{1}} = 0.2\\cdot 10 = 2\\,\\text{V}$, $V_{R_{2}} = 0.2\\cdot 20 = 4\\,\\text{V}$ and $V_{R_{3}} = 0.2\\cdot 30 = 6\\,\\text{V}$, and $2 + 4 + 6 = 12\\,\\text{V}$ ✓: the sum again gives the source voltage."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"A series circuit has $R_{1}=5\\,\\Omega$ and $R_{2}=15\\,\\Omega$, with a $20\\,\\text{V}$ source. What is the total current?","opciones":["$1\\,\\text{A}$","$4\\,\\text{A}$","$0.75\\,\\text{A}$","$20\\,\\text{A}$"],"respuesta":"$1\\,\\text{A}$","explicacion":"$R_{\\text{eq}} = 5+15 = 20\\,\\Omega$. With Ohm's law: $I = \\frac{V}{R_{\\text{eq}}} = \\frac{20}{20} = 1\\,\\text{A}$."},{"pregunta":"What is true about the current in a simple series circuit (a single path, no forks)?","opciones":["It is the same in all the resistors","It is split differently in each resistor","It is zero in the second resistor","It depends on which resistor you look at first"],"respuesta":"It is the same in all the resistors","explicacion":"In series there is no other path for the charge — the same current goes through each resistor, one after the other."},{"pregunta":"In the example circuit ($R_{1}=10\\,\\Omega$, $R_{2}=20\\,\\Omega$, $12\\,\\text{V}$ source, current $0.4\\,\\text{A}$), what is the voltage across $R_{2}$?","opciones":["$8\\,\\text{V}$","$4\\,\\text{V}$","$12\\,\\text{V}$","$0.4\\,\\text{V}$"],"respuesta":"$8\\,\\text{V}$","explicacion":"$V=IR$: $0.4\\,\\text{A}\\times 20\\,\\Omega=8\\,\\text{V}$. And you can check: $4\\,\\text{V}$ (across $R_{1}$) + $8\\,\\text{V}$ (across $R_{2}$) $= 12\\,\\text{V}$, the total of the source."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.leyOhm","despuesDePaso":2,"v":12,"r":30},{"tipo":"circuitia.circuito","despuesDePaso":3,"titulo":"Voltage of each resistor","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":20}]},"vFuente":12,"mostrarValores":"ambas","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":6,"titulo":"Three resistors in series","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":20},{"tipo":"resistor","id":"R3","ohmios":30}]},"vFuente":12,"mostrarValores":"ambas","animarCorriente":true}]$leccion_en$::jsonb
    )
where slug = 'circuitia-pro-fundamentos-ohm-serie';

update public.techniques
set nombre_en = 'Pro Course: Parallel circuits — shared voltage and current split',
    descripcion_en = 'Why parallel branches share the same voltage, how the current is split among them, and a worked example.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["In a PARALLEL circuit, two or more resistors are connected to the same two points (nodes) — that is why the voltage across each of them is EXACTLY the same, no matter how much resistance each branch has.","It is the opposite of what happens in series: there the current was shared and the voltage was split; in parallel it is the VOLTAGE that is shared and the CURRENT that is split among the branches.","Worked example: $R_{1}=10\\,\\Omega$ and $R_{2}=20\\,\\Omega$ in parallel, with a $12\\,\\text{V}$ source. Each resistor sees the full source voltage: $12\\,\\text{V}$ across $R_{1}$ and $12\\,\\text{V}$ across $R_{2}$ too.","Current split (current divider): each branch gets its own current with Ohm's law using ITS resistance: $I_{R_{1}} = \\frac{V}{R_{1}} = \\frac{12}{10} = 1.2\\,\\text{A}$. $I_{R_{2}} = \\frac{V}{R_{2}} = \\frac{12}{20} = 0.6\\,\\text{A}$.","Check with the equivalent resistance: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{10} + \\frac{1}{20} = 0.15$, so $R_{\\text{eq}} = 6.6667\\,\\Omega$, and the total current the source delivers is $I_{\\text{total}} = \\frac{V}{R_{\\text{eq}}} = \\frac{12}{6.6667} = 1.8\\,\\text{A}$ — which matches $I_{R_{1}} + I_{R_{2}} = 1.2 + 0.6 = 1.8\\,\\text{A}$ ✓.","Key insight: the resistor with LESS resistance takes MORE current (it is the \"easier\" path) — it is the inverse relationship. Common mistake: thinking that more resistance attracts more current, it is exactly the opposite."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"$R_{1}=10\\,\\Omega$ and $R_{2}=20\\,\\Omega$ are in parallel with a $12\\,\\text{V}$ source. What is the current through $R_{1}$?","opciones":["$1.2\\,\\text{A}$","$0.6\\,\\text{A}$","$1.8\\,\\text{A}$","$2\\,\\text{A}$"],"respuesta":"$1.2\\,\\text{A}$","explicacion":"In parallel each resistor sees the full source voltage: $I = \\frac{V}{R} = \\frac{12}{10} = 1.2\\,\\text{A}$."},{"pregunta":"What is true about the voltage in a parallel connection?","opciones":["It is the same in all the branches","It is split among the branches","It is zero in the second branch","It depends on the current each branch carries"],"respuesta":"It is the same in all the branches","explicacion":"All the parallel branches are connected to the same two nodes, so they see exactly the same voltage."},{"pregunta":"If two EQUAL resistors are in parallel, how is the total current split between them?","opciones":["It is split equally between the two","All of it goes to the first one","All of it goes to the second one","It depends on which one is drawn on top"],"respuesta":"It is split equally between the two","explicacion":"With the same resistance and the same shared voltage, $I=\\frac{V}{R}$ gives exactly the same value for both branches."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.circuito","despuesDePaso":3,"titulo":"Current through each branch","topologia":{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":20}]},"vFuente":12,"mostrarValores":"corriente","animarCorriente":true},{"tipo":"circuitia.resistenciaEquivalente","despuesDePaso":4,"modo":"paralelo","ohmios":[10,20]}]$leccion_en$::jsonb
    )
where slug = 'circuitia-pro-paralelo-voltaje-corriente';

update public.techniques
set nombre_en = 'Pro Course: Equivalent resistance — series vs. parallel',
    descripcion_en = 'The direct-sum formula (series) against the reciprocal formula (parallel), when to use each one, and a comparison example with the same numbers.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["In SERIES, the equivalent resistance is the direct sum: $R_{\\text{eq}} = R_{1} + R_{2} + \\cdots$ — adding resistors in series ALWAYS increases (or leaves the same) the total resistance.","In PARALLEL, the reciprocals are added and inverted at the end: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\cdots$ — adding resistors in parallel ALWAYS reduces (or leaves the same) the total resistance, because more paths are opened for the current.","Comparison example: two resistors of $8\\,\\Omega$ each. In series: $R_{\\text{eq}} = 8 + 8 = 16\\,\\Omega$.","Those same two $8\\,\\Omega$ resistors, now in parallel: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{8} + \\frac{1}{8} = \\frac{2}{8} = \\frac{1}{4}$, so $R_{\\text{eq}} = 4\\,\\Omega$ — the special case of two equal resistors in parallel: half of a single one, never double.","With an $8\\,\\text{V}$ source across each configuration: in series, $I = \\frac{8}{16} = 0.5\\,\\text{A}$ (the same in both, and each one gets $4\\,\\text{V}$ since they are equal). In parallel, $I_{\\text{total}} = \\frac{8}{4} = 2\\,\\text{A}$, split in equal parts: $1\\,\\text{A}$ for each resistor (because they have the same resistance and see the same voltage).","Quick sanity check: the parallel result $(4\\,\\Omega)$ ALWAYS has to be less than or equal to the smallest resistor of the branch $(8\\,\\Omega)$ — if it gives you a larger one, you inverted something too many or too few times in the reciprocal formula."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Two resistors of $8\\,\\Omega$ each are in series. What is the equivalent resistance?","opciones":["$16\\,\\Omega$","$4\\,\\Omega$","$8\\,\\Omega$","$64\\,\\Omega$"],"respuesta":"$16\\,\\Omega$","explicacion":"In series they are added directly: $8+8=16\\,\\Omega$."},{"pregunta":"Those same two $8\\,\\Omega$ resistors, now in parallel. What is the equivalent resistance?","opciones":["$4\\,\\Omega$","$16\\,\\Omega$","$8\\,\\Omega$","$2\\,\\Omega$"],"respuesta":"$4\\,\\Omega$","explicacion":"$\\frac{1}{R_{\\text{eq}}}=\\frac{1}{8}+\\frac{1}{8}=\\frac{1}{4}$, so $R_{\\text{eq}}=4\\,\\Omega$ — half of a single one, the special case of two equal resistors in parallel."},{"pregunta":"What is the correct formula for the equivalent resistance of several resistors in PARALLEL?","opciones":["$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\cdots$","$R_{\\text{eq}} = R_{1} + R_{2} + \\cdots$","$R_{\\text{eq}} = (R_{1} + R_{2}) / 2$","$R_{\\text{eq}} = R_{1} + R_{2} + 10$"],"respuesta":"$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\cdots$","explicacion":"It is the sum of reciprocals, inverted at the end — never the direct sum (that is the series formula, not the parallel one)."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.resistenciaEquivalente","despuesDePaso":2,"modo":"serie","ohmios":[8,8]},{"tipo":"circuitia.resistenciaEquivalente","despuesDePaso":3,"modo":"paralelo","ohmios":[8,8]}]$leccion_en$::jsonb
    )
where slug = 'circuitia-pro-resistencia-equivalente-comparacion';

update public.techniques
set nombre_en = 'Pro Course: Mixed circuits — identify the parallel block first',
    descripcion_en = 'The reading strategy for a mixed circuit: find the parallel block before calculating anything, and collapse it to a single value.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A mixed circuit combines a series branch with a parallel block embedded inside it — it is solved from the INSIDE OUT, never by adding everything at once.","How to find the parallel block at a glance: look for the group of resistors that share the same two nodes — it is usually drawn as the most nested or smallest stretch of the circuit, not on the main line.","Worked example: a series circuit with $R_{s1}=10\\,\\Omega$ and a parallel block formed by $R_{p1}=20\\,\\Omega$ and $R_{p2}=20\\,\\Omega$.","Step 1 — collapse the parallel block ALONE (in isolation, before touching $R_{s1}$): $\\frac{1}{R_{\\text{block}}} = \\frac{1}{20} + \\frac{1}{20} = \\frac{1}{10}$, so $R_{\\text{block}} = 10\\,\\Omega$.","Step 2 — with the block already collapsed to a single value, the whole circuit becomes a simple series of two resistors: $R_{\\text{eq total}} = R_{s1} + R_{\\text{block}} = 10 + 10 = 20\\,\\Omega$.","Common mistake to avoid: adding $R_{s1} + R_{p1} + R_{p2}$ all together as if the three were in series — $R_{p1}$ and $R_{p2}$ have to be collapsed to ONE single value with the reciprocal formula BEFORE they can be added to the rest of the series."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"In a series circuit with $R_{s1}=10\\,\\Omega$ and a parallel block of $R_{p1}=20\\,\\Omega$ and $R_{p2}=20\\,\\Omega$, what is the equivalent resistance of the parallel block, before adding it to the rest?","opciones":["$10\\,\\Omega$","$20\\,\\Omega$","$40\\,\\Omega$","$5\\,\\Omega$"],"respuesta":"$10\\,\\Omega$","explicacion":"$\\frac{1}{R_{\\text{block}}}=\\frac{1}{20}+\\frac{1}{20}=\\frac{1}{10}$, so $R_{\\text{block}}=10\\,\\Omega$ — the case of two equal resistors in parallel, half of a single one."},{"pregunta":"With $R_{s1}=10\\,\\Omega$ and the parallel block already collapsed to $10\\,\\Omega$, what is the equivalent resistance of the whole circuit?","opciones":["$20\\,\\Omega$","$10\\,\\Omega$","$30\\,\\Omega$","$200\\,\\Omega$"],"respuesta":"$20\\,\\Omega$","explicacion":"Now it is a simple series of two values: $10\\,\\Omega$ ($R_{s1}$) $+ 10\\,\\Omega$ (the collapsed block) $= 20\\,\\Omega$."},{"pregunta":"What is the correct first step to read a mixed circuit (series with a parallel block inside)?","opciones":["Identify the parallel block and calculate its equivalent resistance first","Add all the resistances directly without looking at how they are connected","Ignore the parallel block and treat it as if it were not there","Calculate the current before knowing any resistance"],"respuesta":"Identify the parallel block and calculate its equivalent resistance first","explicacion":"The parallel block has to be collapsed to ONE single value before it can be added in series with the rest — the two formulas are never mixed over the loose resistors."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.circuito","despuesDePaso":2,"titulo":"The whole circuit","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"Rs1","ohmios":10},{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"Rp1","ohmios":20},{"tipo":"resistor","id":"Rp2","ohmios":20}]}]},"vFuente":12,"resaltarId":"Rp1","mostrarValores":"ninguna","animarCorriente":false},{"tipo":"circuitia.resistenciaEquivalente","despuesDePaso":3,"modo":"paralelo","ohmios":[20,20]}]$leccion_en$::jsonb
    )
where slug = 'circuitia-pro-mixtos-identificar-bloque';

update public.techniques
set nombre_en = 'Pro Course: Mixed circuits — solving them step by step',
    descripcion_en = 'The complete two-pass algorithm (the same one the solver kernel uses): equivalent resistance from the bottom up, and then splitting current/voltage from the top down.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The complete algorithm has two passes: 1) from the BOTTOM UP, the total equivalent resistance is calculated and with it the total current the source delivers; 2) from the TOP DOWN, that current/voltage is split from the source to each resistor, respecting that in series the current is shared and in parallel the voltage is shared.","Worked example: $R_{s1}=5\\,\\Omega$ in series with a parallel block ($R_{p1}=20\\,\\Omega$, $R_{p2}=20\\,\\Omega$) and then $R_{s2}=5\\,\\Omega$, with a $20\\,\\text{V}$ source.","Pass 1 (bottom up): first the block, $\\frac{1}{R_{\\text{block}}} = \\frac{1}{20} + \\frac{1}{20} = \\frac{1}{10} \\to R_{\\text{block}} = 10\\,\\Omega$. Then the whole series: $R_{\\text{eq total}} = R_{s1} + R_{\\text{block}} + R_{s2} = 5 + 10 + 5 = 20\\,\\Omega$. And with that, the total current: $I_{\\text{total}} = \\frac{V}{R_{\\text{eq}}} = \\frac{20}{20} = 1\\,\\text{A}$ — this current goes through $R_{s1}$, the block (as a whole) and $R_{s2}$, because the three are in series with each other.","Pass 2 (top down, first level): each series stretch gets $V=I_{\\text{total}}\\times R_{\\text{stretch}}$. $V_{R_{s1}} = 1\\times 5 = 5\\,\\text{V}$. $V_{\\text{block}} = 1\\times 10 = 10\\,\\text{V}$. $V_{R_{s2}} = 1\\times 5 = 5\\,\\text{V}$. Check: $5+10+5 = 20\\,\\text{V}$, exactly the source voltage ✓.","Pass 2 (one level further in, inside the block): now $R_{p1}$ and $R_{p2}$ share the voltage of the block you already calculated $(10\\,\\text{V})$ — each one gets its own current with Ohm's law: $I_{R_{p1}} = \\frac{10}{20} = 0.5\\,\\text{A}$, $I_{R_{p2}} = \\frac{10}{20} = 0.5\\,\\text{A}$.","Final check: all the current that enters the block has to leave split among its branches — $I_{R_{p1}} + I_{R_{p2}} = 0.5 + 0.5 = 1\\,\\text{A}$, which matches $I_{\\text{total}}$ exactly. If that sum did not match, something was calculated wrong in some previous step."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"In the circuit $R_{s1}=5\\,\\Omega$ + parallel block ($10\\,\\Omega$ equivalent) + $R_{s2}=5\\,\\Omega$, with a $20\\,\\text{V}$ source, what is the total current the source delivers?","opciones":["$1\\,\\text{A}$","$2\\,\\text{A}$","$0.5\\,\\text{A}$","$4\\,\\text{A}$"],"respuesta":"$1\\,\\text{A}$","explicacion":"$R_{\\text{eq total}} = 5+10+5 = 20\\,\\Omega$. $I = \\frac{V}{R} = \\frac{20}{20} = 1\\,\\text{A}$."},{"pregunta":"With that total current of $1\\,\\text{A}$, what is the voltage across the parallel block ($10\\,\\Omega$ equivalent)?","opciones":["$10\\,\\text{V}$","$5\\,\\text{V}$","$20\\,\\text{V}$","$1\\,\\text{V}$"],"respuesta":"$10\\,\\text{V}$","explicacion":"$V=IR$: $1\\,\\text{A}\\times 10\\,\\Omega=10\\,\\text{V}$ — the whole block acts as a single $10\\,\\Omega$ resistor inside the series."},{"pregunta":"Knowing that the parallel block has $10\\,\\text{V}$ across its terminals and $R_{p1}=R_{p2}=20\\,\\Omega$, how much current goes through $R_{p1}$?","opciones":["$0.5\\,\\text{A}$","$1\\,\\text{A}$","$0.25\\,\\text{A}$","$2\\,\\text{A}$"],"respuesta":"$0.5\\,\\text{A}$","explicacion":"Inside the block, each branch sees the shared voltage of the block $(10\\,\\text{V})$: $I=\\frac{V}{R}=\\frac{10}{20}=0.5\\,\\text{A}$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.leyOhm","despuesDePaso":2,"v":20,"r":20},{"tipo":"circuitia.circuito","despuesDePaso":4,"titulo":"Complete result","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"Rs1","ohmios":5},{"tipo":"paralelo","hijos":[{"tipo":"resistor","id":"Rp1","ohmios":20},{"tipo":"resistor","id":"Rp2","ohmios":20}]},{"tipo":"resistor","id":"Rs2","ohmios":5}]},"vFuente":20,"mostrarValores":"ambas","animarCorriente":true}]$leccion_en$::jsonb
    )
where slug = 'circuitia-pro-mixtos-resolver-paso-a-paso';

update public.techniques
set nombre_en = 'Pro Course: Qualitative reasoning — how a current changes without calculating everything',
    descripcion_en = 'The quick rule to know whether a current goes up or down when a resistor changes, without solving the whole circuit — with one example that increases and one that decreases.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["General rule: in a single series path, increasing the resistance anywhere ALWAYS reduces (or leaves the same) the total current; it never increases it. And the other way round: reducing a resistance always increases (or leaves the same) the current.","Base circuit: series with $R_{1}=10\\,\\Omega$ and $R_{2}=10\\,\\Omega$, $20\\,\\text{V}$ source. $R_{\\text{eq}} = 20\\,\\Omega$, base current $I = \\frac{20}{20} = 1\\,\\text{A}$ — the same in $R_{1}$ and in $R_{2}$, because they are in series.","Disturbance A — $R_{1}$ doubles to $20\\,\\Omega$: new $R_{\\text{eq}} = 20+10 = 30\\,\\Omega$, new current $I = \\frac{20}{30} \\approx 0.667\\,\\text{A}$. Result: it DECREASES compared with the base (from $1\\,\\text{A}$ to $\\approx 0.667\\,\\text{A}$), because the path now has more total resistance.","Disturbance B — instead, $R_{1}$ is halved, to $5\\,\\Omega$: new $R_{\\text{eq}} = 5+10 = 15\\,\\Omega$, new current $I = \\frac{20}{15} \\approx 1.333\\,\\text{A}$. Result: it INCREASES compared with the base (from $1\\,\\text{A}$ to $\\approx 1.333\\,\\text{A}$), because the path now has less total resistance.","Why it works without solving everything: in a single series path, the current depends only on the TOTAL resistance of that path $(I=\\frac{V}{R_{\\text{eq}}})$ — if that sum goes up, the current goes down (or stays the same); if that sum goes down, the current goes up (or stays the same). Never the other way round.","Quick application: to estimate the DIRECTION of the change it is enough to ask yourself \"did the total resistance of the path go up or down?\" — there is no need to recalculate the whole circuit for that, although for the exact VALUE you do have to solve it step by step.","The voltage can also be anticipated. In the base circuit each resistor has $10\\,\\text{V}$ (it is $1\\,\\text{A}\\cdot 10\\,\\Omega$). If $R_{1}$ doubles to $20\\,\\Omega$, the current goes down to $\\approx 0.67\\,\\text{A}$: $R_{1}$ goes to $\\approx 13.33\\,\\text{V}$ and its neighbor $R_{2}$ goes down to $\\approx 6.67\\,\\text{V}$. If $R_{1}$ is reduced to $5\\,\\Omega$, the current goes up to $\\approx 1.33\\,\\text{A}$: $R_{1}$ goes to $\\approx 6.67\\,\\text{V}$ and $R_{2}$ goes up to $\\approx 13.33\\,\\text{V}$. The total voltage is still $20\\,\\text{V}$: what one series resistor gains, the other loses."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"In a series circuit $R_{1}=10\\,\\Omega$ and $R_{2}=10\\,\\Omega$ with a $20\\,\\text{V}$ source (base current $1\\,\\text{A}$), if $R_{1}$ doubles to $20\\,\\Omega$, what happens to the total current?","opciones":["It decreases","It increases","It does not change","It becomes zero"],"respuesta":"It decreases","explicacion":"The total resistance goes up from $20\\,\\Omega$ to $30\\,\\Omega$, so the current goes down: from $1\\,\\text{A}$ to $\\frac{20}{30}\\approx 0.67\\,\\text{A}$."},{"pregunta":"In the same circuit, if instead $R_{1}$ is halved (to $5\\,\\Omega$), what happens to the total current?","opciones":["It increases","It decreases","It does not change","It becomes infinite"],"respuesta":"It increases","explicacion":"The total resistance goes down from $20\\,\\Omega$ to $15\\,\\Omega$, so the current goes up: from $1\\,\\text{A}$ to $\\frac{20}{15}\\approx 1.33\\,\\text{A}$."},{"pregunta":"Why does increasing the resistance of any resistor in a simple series circuit ALWAYS make the current go down or stay the same, never go up?","opciones":["Because the total resistance of the circuit (the sum of all of them) can only increase or stay the same, never go down","Because the source automatically reduces its voltage when it detects the change","Because the current chooses the shortest available path","Because series resistors cancel each other out"],"respuesta":"Because the total resistance of the circuit (the sum of all of them) can only increase or stay the same, never go down","explicacion":"In series, $R_{\\text{eq}}$ is a SUM of positive resistances — adding more can never shrink that sum, and a bigger current $(I=\\frac{V}{R_{\\text{eq}}})$ would need a smaller $R_{\\text{eq}}$, not a bigger one."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"circuitia.circuito","despuesDePaso":1,"titulo":"Base circuit","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R1","mostrarValores":"corriente","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":2,"titulo":"R1 doubles to 20Ω: the current goes down","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":20},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R1","mostrarValores":"corriente","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":3,"titulo":"R1 is reduced to 5Ω: the current goes up","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":5},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R1","mostrarValores":"corriente","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":6,"titulo":"Base: 1 A and 10 V in each resistor","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":10},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R2","mostrarValores":"ambas","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":6,"titulo":"R1 doubles to 20Ω: R2 gets less current and less voltage","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":20},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R2","mostrarValores":"ambas","animarCorriente":true},{"tipo":"circuitia.circuito","despuesDePaso":6,"titulo":"R1 is reduced to 5Ω: R2 gets more current and more voltage","topologia":{"tipo":"serie","hijos":[{"tipo":"resistor","id":"R1","ohmios":5},{"tipo":"resistor","id":"R2","ohmios":10}]},"vFuente":20,"resaltarId":"R2","mostrarValores":"ambas","animarCorriente":true}]$leccion_en$::jsonb
    )
where slug = 'circuitia-pro-cualitativo-sube-o-baja';

update public.techniques
set nombre_en = 'Pro Course: Qualitative reasoning — when something genuinely does NOT change',
    descripcion_en = 'The legitimate (and sometimes counterintuitive) case of "it does not change": a parallel branch connected directly to the source is not affected by changes in its sibling branches.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["In a parallel block connected DIRECTLY to the source, each branch always sees the same voltage (the source's), no matter what happens in the sibling branches — and since the current of each branch is $I=\\frac{V}{R_{\\text{own}}}$, that current does NOT depend on the siblings either.","Concrete case, already verified in the solver kernel (resolver.test.ts): a parallel circuit with $R_{1}=4\\,\\Omega$, $R_{2}=6\\,\\Omega$ and $R_{3}=12\\,\\Omega$, $12\\,\\text{V}$ source. Base currents: $I_{R_{1}} = \\frac{12}{4} = 3\\,\\text{A}$, $I_{R_{2}} = \\frac{12}{6} = 2\\,\\text{A}$, $I_{R_{3}} = \\frac{12}{12} = 1\\,\\text{A}$.","Disturbance: $R_{2}$ doubles to $12\\,\\Omega$. New $I_{R_{2}} = \\frac{12}{12} = 1\\,\\text{A}$ — that one DID change (from $2\\,\\text{A}$ to $1\\,\\text{A}$), it makes sense because ITS OWN resistance changed.","But $I_{R_{3}}$ is still $\\frac{12}{12} = 1\\,\\text{A}$, exactly as before — it does NOT CHANGE, even though $R_{2}$ (its \"sibling\" in the same block) changed. For the same reason, $I_{R_{1}}$ does not change either (it stays at $3\\,\\text{A}$).","Why it is not a calculation mistake: the voltage $R_{3}$ sees is always the source's ($12\\,\\text{V}$, fixed), because $R_{3}$ is connected directly to the same two nodes as the source — the resistance of $R_{2}$ does not enter any calculation of $I_{R_{3}}=\\frac{V}{R_{3}}$. Changing $R_{2}$ does change how much TOTAL current the source delivers (from $6\\,\\text{A}$ to $5\\,\\text{A}$), but that difference is absorbed ONLY by the branch that changed, not by the siblings.","Common mistake to avoid: assuming that \"changing something in the circuit always affects the whole circuit\". In a pure parallel block connected directly to the source, a change in one branch stays isolated in that branch; it would only spread to the siblings if there were something in series shared between the block and the source (as in the mixed circuit lessons).","The same goes for voltage and for reducing a resistance. With $R_{1}=4\\,\\Omega$, $R_{2}=6\\,\\Omega$, $R_{3}=12\\,\\Omega$ and $12\\,\\text{V}$, each branch has $12\\,\\text{V}$ and their currents are $3\\,\\text{A}$, $2\\,\\text{A}$ and $1\\,\\text{A}$. If $R_{2}$ doubles to $12\\,\\Omega$, its current goes down to $1\\,\\text{A}$; if it is halved, to $3\\,\\Omega$, it goes up to $4\\,\\text{A}$. In both cases $R_{3}$ keeps $12\\,\\text{V}$ and $1\\,\\text{A}$, and $R_{1}$ keeps $12\\,\\text{V}$ and $3\\,\\text{A}$: a sibling branch changed, not its voltage or its resistance.","In a mixed circuit the answer changes, because the branches of the block share a resistor in series with the source. With $R_{s1}=10\\,\\Omega$ in series with the block $R_{p1}=20\\,\\Omega$ and $R_{p2}=20\\,\\Omega$, and a $12\\,\\text{V}$ source, $R_{s1}$ has $0.6\\,\\text{A}$ and $6\\,\\text{V}$, and each branch of the block has $0.3\\,\\text{A}$ and $6\\,\\text{V}$. If $R_{p2}$ doubles to $40\\,\\Omega$, the block offers more resistance, the total current goes down to $\\approx 0.51\\,\\text{A}$, $R_{s1}$ keeps $\\approx 5.14\\,\\text{V}$ and $\\approx 6.86\\,\\text{V}$ reach the block: $R_{p1}$ goes to $\\approx 0.34\\,\\text{A}$, that is, it INCREASES, and $R_{p2}$ to $\\approx 0.17\\,\\text{A}$. If $R_{p2}$ is reduced to $10\\,\\Omega$, the block offers less resistance, the total current goes up to $0.72\\,\\text{A}$, $R_{s1}$ takes $7.2\\,\\text{V}$ and $4.8\\,\\text{V}$ are left for the block: $R_{p1}$ goes down to $0.24\\,\\text{A}$, that is, it DECREASES, and $R_{p2}$ goes up to $0.48\\,\\text{A}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"In a parallel circuit with $R_{1}=4\\,\\Omega$, $R_{2}=6\\,\\Omega$ and $R_{3}=12\\,\\Omega$ connected directly to a $12\\,\\text{V}$ source, if $R_{2}$ doubles to $12\\,\\Omega$, what happens to the current in $R_{3}$?","opciones":["It does not change","It increases","It decreases","It becomes zero"],"respuesta":"It does not change","explicacion":"$I_{R_{3}}=\\frac{V}{R_{3}}=\\frac{12}{12}=1\\,\\text{A}$ before and after — it does not depend on $R_{2}$ because $R_{3}$ still sees the same source voltage."},{"pregunta":"Why does the current of $R_{3}$ not change in that case, even though $R_{2}$ did change?","opciones":["Because in a parallel block connected directly to the source, each branch always sees the same fixed voltage, and its current depends only on its own resistance","Because $R_{3}$ is drawn farther from the source than $R_{2}$","Because the total current of the circuit never changes","Because $R_{2}$ and $R_{3}$ cancel each other out"],"respuesta":"Because in a parallel block connected directly to the source, each branch always sees the same fixed voltage, and its current depends only on its own resistance","explicacion":"The voltage of a pure parallel block connected to the source is always the source's — no sibling branch can change that value for $R_{3}$."},{"pregunta":"What DOES change in that same circuit when $R_{2}$ doubles?","opciones":["The current through $R_{2}$ itself, and the total current the source delivers","The current of $R_{1}$","The voltage of $R_{3}$","Nothing changes at all"],"respuesta":"The current through $R_{2}$ itself, and the total current the source delivers","explicacion":"$I_{R_{2}}$ goes down from $2\\,\\text{A}$ to $1\\,\\text{A}$ (its own resistance changed), and therefore the total current of the source goes down from $6\\,\\text{A}$ to $5\\,\\text{A}$ — but that does not alter the sibling branches that did not change."}]$leccion_en$::jsonb,
